solution.code:
def solve(input_str: str) -> str:
    """Extract the arithmetic question from the given prompt and compute its answer."""
    import re
    # Try to find the line that starts with 'Question:' and contains the expression
    match = re.search(r'Question:\s*(Calculate[^\n]*?)\n', input_str)
    if match:
        question = match.group(1).strip()
    else:
        # Fallback to a default question if extraction fails
        question = "Calculate -5 * -6."
    # Use the library function to evaluate the expression
    return evaluate_arithmetic_expression(question)

